const t={maxFlow:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Trova il flusso volumetrico massimo (mm³/s) che il tuo hotend riesce a sostenere - aumentando il flusso mentre osservi il carico StallGuard dell'estrusore per cogliere l'istante in cui l'ingranaggio slitta. Visualizza prima il piano; il test live riscalda ed estrude, quindi prepara la stampante prima di avviarlo."}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Aiuto"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Informazioni su Max-Flow"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Chiudi"}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:"Come si usa"}},steps:[{t:0,b:{t:2,i:[{t:3}],s:"Imposta la temperatura di test e il diametro del filamento (scegli un hotend per precompilare)."}},{t:0,b:{t:2,i:[{t:3}],s:"Visualizza il piano - mostra ogni step di flusso e quanto filamento spinge."}},{t:0,b:{t:2,i:[{t:3}],s:"Spunta la checklist di sicurezza, poi avvia il test live (riscalda + estrude)."}},{t:0,b:{t:2,i:[{t:3}],s:"Leggi il flusso massimo sostenuto e copia il valore suggerito per lo slicer."}}],topics:{howItWorks:{title:{t:0,b:{t:2,i:[{t:3}],s:"Come funziona il test"}},body:{t:0,b:{t:2,i:[{t:3}],s:"L'estrusore spinge il filamento a un flusso volumetrico in costante aumento. Finché l'ingranaggio dentato fa presa in modo pulito, la lettura del carico StallGuard resta stabile; quando inizia a slittare le letture iniziano a oscillare. Il flusso più alto raggiunto prima di quel salto è il tuo flusso massimo sostenibile. La rampa si ferma non appena viene rilevato lo slittamento, così nessun filamento viene macinato oltre il primo slittamento."}}},stallguard:{title:{t:0,b:{t:2,i:[{t:3}],s:"Rilevamento slittamento StallGuard"}},body:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard è una funzione dei driver TMC che riporta il carico del motore. Questo test lo campiona molte volte per ogni step di flusso e cerca un improvviso aumento della dispersione (IQR) o della variazione (CV) - la firma dell'ingranaggio che perde presa. Le soglie provengono da un profilo specifico per driver. Nota: su un estrusore TMC2209 viene usato il percorso sperimentale SG4, quindi considera la prima esecuzione come una calibrazione."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"Sicurezza"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Questo è un test caldo e in movimento che fa slittare deliberatamente l'estrusore. Carica il filamento, assicurati che l'ugello sia libero (sopra il piano o un'area di scarto) e resta nelle vicinanze. L'esecuzione viene rifiutata mentre la stampante sta stampando, e il riscaldatore viene sempre spento al termine."}}},slicer:{title:{t:0,b:{t:2,i:[{t:3}],s:"Usare il risultato"}},body:{t:0,b:{t:2,i:[{t:3}],s:`Inserisci il valore suggerito nella "velocità volumetrica massima" del tuo slicer (per filamento). Il valore conservativo (80% del massimo misurato) è un limite sicuro per l'uso quotidiano; il valore bilanciato (90%) spinge un po' di più. Temperature più alte dell'hotend di solito aumentano il flusso raggiungibile.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Glossario"}},body:{t:0,b:{static:"",t:2,i:[]}}}},glossary:{flow:{term:{t:0,b:{t:2,i:[{t:3}],s:"Flusso volumetrico"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Quanta plastica l'hotend fonde al secondo (mm³/s) - il vero limite di velocità per la stampa veloce."}}},stallguard:{term:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Un segnale dei driver TMC che riporta il carico meccanico del motore, qui usato per rilevare lo slittamento dell'estrusore."}}},slip:{term:{t:0,b:{t:2,i:[{t:3}],s:"Slittamento"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Quando l'ingranaggio dell'estrusore non riesce più a fare presa sul filamento abbastanza rapidamente e salta - il limite massimo del flusso."}}},meltzone:{term:{t:0,b:{t:2,i:[{t:3}],s:"Zona di fusione"}},def:{t:0,b:{t:2,i:[{t:3}],s:"La lunghezza riscaldata dell'hotend; una zona di fusione più lunga (es. Volcano) sostiene un flusso più alto."}}}}},params:{title:{t:0,b:{t:2,i:[{t:3}],s:"Parametri del test"}},temperature:{t:0,b:{t:2,i:[{t:3}],s:"Temperatura (°C)"}},filamentDiameter:{t:0,b:{t:2,i:[{t:3}],s:"Ø filamento (mm)"}},hotend:{t:0,b:{t:2,i:[{t:3}],s:"Hotend (opzionale)"}},hotendNone:{t:0,b:{t:2,i:[{t:3}],s:"- nessuno -"}},hotendHint:{t:0,b:{t:2,i:[{t:3,v:"Previsto ~"},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},startFlow:{t:0,b:{t:2,i:[{t:3}],s:"Flusso iniziale (mm³/s)"}},endFlow:{t:0,b:{t:2,i:[{t:3}],s:"Flusso finale (mm³/s)"}},stepFlow:{t:0,b:{t:2,i:[{t:3}],s:"Step (mm³/s)"}},samples:{t:0,b:{t:2,i:[{t:3}],s:"Campioni / step"}},extrudePerStep:{t:0,b:{t:2,i:[{t:3}],s:"Estrusione / step (mm)"}},driver:{t:0,b:{t:2,i:[{t:3}],s:"Driver estrusore"}},driverDetected:{t:0,b:{t:2,i:[{t:3}],s:"rilevato dalla stampante"}},autoStealthchop:{t:0,b:{t:2,i:[{t:3}],s:"Abilita automaticamente StealthChop per il test"}},autoStealthchopHint:{t:0,b:{t:2,i:[{t:3}],s:"Solo TMC2209/2240: scrive temporaneamente uno stealthchop_threshold sull'estrusore così che StallGuard possa leggere, poi lo commenta dopo il test. Ripristina printer.cfg; riavvio firmware in entrambi i casi."}},method:{t:0,b:{t:2,i:[{t:3}],s:"Metodo di rilevamento"}},methodHint:{t:0,b:{t:2,i:[{t:3}],s:"Auto usa StallGuard, ripiegando sull'accelerometro della testina (vibrazione) quando StallGuard non riesce a leggere. Il metodo con accelerometro è sperimentale."}}},method:{auto:{t:0,b:{t:2,i:[{t:3}],s:"Auto"}},stallguard:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard"}},accel:{t:0,b:{t:2,i:[{t:3}],s:"Accelerometro"}}},plan:{button:{t:0,b:{t:2,i:[{t:3}],s:"Visualizza piano"}},title:{t:0,b:{t:2,i:[{t:3}],s:"Rampa pianificata"}},stepCount:{t:0,b:{t:2,i:[{t:4,k:"count"},{t:3,v:" step"}]}},totalExtrude:{t:0,b:{t:2,i:[{t:4,k:"mm"},{t:3,v:" mm di filamento"}]}},sgField:{t:0,b:{t:2,i:[{t:3,v:"Campo StallGuard: "},{t:4,k:"field"}]}},sgFieldUnknown:{t:0,b:{t:2,i:[{t:3}],s:"Nessun campo StallGuard noto per questo driver"}},flowHead:{t:0,b:{t:2,i:[{t:3}],s:"Flusso (mm³/s)"}},feedrateHead:{t:0,b:{t:2,i:[{t:3}],s:"Avanzamento (mm/min)"}},warning:{t:0,b:{t:2,i:[{t:3}],s:"Il test live riscalda l'hotend ed estrude filamento, deliberatamente fino al punto di slittamento. Solo anteprima - non viene ancora eseguito nulla."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"Prima di avviare - checklist di sicurezza"}},items:[{t:0,b:{t:2,i:[{t:3}],s:"Il filamento è caricato e avanza liberamente."}},{t:0,b:{t:2,i:[{t:3}],s:"L'ugello è libero - sopra il piano o un cestino di scarto, non a mezz'aria sopra i pezzi."}},{t:0,b:{t:2,i:[{t:3}],s:"Accetto che questo macinerà/farà slittare deliberatamente del filamento."}},{t:0,b:{t:2,i:[{t:3}],s:"Resterò accanto alla stampante per tutta la durata del test."}}],ack:{t:0,b:{t:2,i:[{t:3}],s:"Ho fatto tutto quanto sopra e la stampante è pronta"}},note:{t:0,b:{t:2,i:[{t:3}],s:"L'esecuzione viene rifiutata durante la stampa; il riscaldatore viene spento automaticamente alla fine."}}},run:{button:{t:0,b:{t:2,i:[{t:3}],s:"Avvia test live"}},running:{t:0,b:{t:2,i:[{t:3}],s:"In esecuzione… (riscaldamento + estrusione)"}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:"Avviare il test live max-flow?"}},confirmBody:{t:0,b:{t:2,i:[{t:3,v:"Questo riscalda l'hotend a "},{t:4,k:"temp"},{t:3,v:" °C ed estrude fino a "},{t:4,k:"mm"},{t:3,v:" mm di filamento, aumentando finché l'estrusore non slitta."}]}},confirm:{t:0,b:{t:2,i:[{t:3}],s:"Avvia ora"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Annulla"}},busy:{t:0,b:{t:2,i:[{t:3}],s:"Rifiutato: la stampante è occupata (in stampa o in pausa). Riprova quando è inattiva."}},error:{t:0,b:{t:2,i:[{t:3}],s:"Il test non è riuscito."}},noSg:{t:0,b:{t:2,i:[{t:3}],s:"Nessun campione StallGuard è stato letto - il risultato dello slittamento potrebbe essere inaffidabile. Il campo SG live del driver probabilmente va regolato per questo modello."}},progress:{t:0,b:{t:2,i:[{t:3,v:"Step "},{t:4,k:"step"},{t:3,v:"/"},{t:4,k:"total"},{t:3,v:" - "},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},starting:{t:0,b:{t:2,i:[{t:3}],s:"Riscaldamento / avvio…"}},abort:{t:0,b:{t:2,i:[{t:3}],s:"Interrompi esecuzione"}},cancelling:{t:0,b:{t:2,i:[{t:3}],s:"Interruzione in corso…"}},cancelled:{t:0,b:{t:2,i:[{t:3}],s:"Esecuzione interrotta - il riscaldatore è stato spento."}},reattached:{t:0,b:{t:2,i:[{t:3}],s:"Riconnesso: questo risultato è stato completato mentre la pagina era assente."}},failed:{t:0,b:{t:2,i:[{t:3}],s:"Esecuzione max-flow non riuscita."}},abortNote:{t:0,b:{t:2,i:[{t:3}],s:"L'interruzione spegne sempre il riscaldatore."}},parkNote:{t:0,b:{t:2,i:[{t:3}],s:"Prima del riscaldamento, la stampante esegue l'homing (se necessario) e centra l'ugello per una visuale libera."}},phase:{enabling:{t:0,b:{t:2,i:[{t:3}],s:"Abilitazione di StealthChop…"}},homing:{t:0,b:{t:2,i:[{t:3}],s:"Homing della stampante…"}},centering:{t:0,b:{t:2,i:[{t:3}],s:"Centratura dell'ugello…"}},heating:{t:0,b:{t:2,i:[{t:3}],s:"Riscaldamento dell'hotend…"}},checking:{t:0,b:{t:2,i:[{t:3}],s:"Verifica del segnale StallGuard…"}},ramp:{t:0,b:{t:2,i:[{t:3}],s:"Aumento del flusso…"}},reverting:{t:0,b:{t:2,i:[{t:3}],s:"Ripristino della configurazione…"}}},step:{home:{t:0,b:{t:2,i:[{t:3}],s:"Home"}},center:{t:0,b:{t:2,i:[{t:3}],s:"Centra"}},heat:{t:0,b:{t:2,i:[{t:3}],s:"Riscalda"}},check:{t:0,b:{t:2,i:[{t:3}],s:"Verifica"}},ramp:{t:0,b:{t:2,i:[{t:3}],s:"Rampa"}}}},camera:{title:{t:0,b:{t:2,i:[{t:3}],s:"Camera live"}},live:{t:0,b:{t:2,i:[{t:3}],s:"LIVE"}},error:{t:0,b:{t:2,i:[{t:3}],s:"Camera non disponibile."}},willShow:{t:0,b:{t:2,i:[{t:3}],s:"Una visuale live della camera mostrerà l'ugello durante il test."}},minimize:{t:0,b:{t:2,i:[{t:3}],s:"Riduci a icona"}},maximize:{t:0,b:{t:2,i:[{t:3}],s:"Massimizza"}},enlarge:{t:0,b:{t:2,i:[{t:3}],s:"Ingrandisci"}},shrink:{t:0,b:{t:2,i:[{t:3}],s:"Rimpicciolisci"}}},result:{title:{t:0,b:{t:2,i:[{t:3}],s:"Risultato"}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:"Flusso massimo sostenuto"}},slipAt:{t:0,b:{t:2,i:[{t:3,v:"Slittamento rilevato a "},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},noSlip:{t:0,b:{t:2,i:[{t:3}],s:"Nessuno slittamento fino al flusso massimo testato"}},reason:{t:0,b:{t:2,i:[{t:3}],s:"Dettaglio"}},recommendTitle:{t:0,b:{t:2,i:[{t:3}],s:"Valori suggeriti per lo slicer (velocità volumetrica massima)"}},conservative:{t:0,b:{t:2,i:[{t:3}],s:"Conservativo (80%)"}},balanced:{t:0,b:{t:2,i:[{t:3}],s:"Bilanciato (90%)"}},units:{t:0,b:{t:2,i:[{t:3}],s:"mm³/s"}},fromBefore:{t:0,b:{t:2,i:[{t:3,v:"Misurato in precedenza ("},{t:4,k:"at"},{t:3,v:") - esegui di nuovo per numeri aggiornati."}]}},unreliableTitle:{t:0,b:{t:2,i:[{t:3}],s:"Inaffidabile - nessun segnale StallGuard"}},unmeasured:{t:0,b:{t:2,i:[{t:3}],s:"raggiunto, non confermato"}},via:{t:0,b:{t:2,i:[{t:3,v:"Misurato tramite "},{t:4,k:"method"}]}},accelExperimental:{t:0,b:{t:2,i:[{t:3}],s:"Misurato per vibrazione (accelerometro) - sperimentale; considera il numero come una guida, non un limite esatto."}}},states:{loadingHotends:{t:0,b:{t:2,i:[{t:3}],s:"Caricamento hotend…"}}}}};export{t as default};
